package me.neobliz1.ecomonitoring.platform.history.infrastructure.adapter.outbound.persistence.postgres.jpa;import static me.neobliz1.ecomonitoring.platform.history.domain.model.constant.HistoricalCacheConstants.BUCKETS_GLOBAL_REGION;import jakarta.persistence.QueryHint;import me.neobliz1.ecomonitoring.platform.history.domain.model.entity.WeatherMapBucket;import org.hibernate.jpa.HibernateHints;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.QueryHints;import org.springframework.stereotype.Repository;import java.util.List;import java.util.Optional;import java.util.UUID;@Repositorypublic interface HistoricalWeatherMapJpaRepository extends JpaRepository<WeatherMapBucket, UUID> {    @QueryHints(value = {            @QueryHint(name = HibernateHints.HINT_CACHEABLE, value = "true"),            @QueryHint(name = HibernateHints.HINT_CACHE_REGION, value = BUCKETS_GLOBAL_REGION)    })    Optional<WeatherMapBucket> findByTimestampBucketAndIntervalMinutes(Long timestampBucket, Integer intervalMinutes);    @QueryHints(value = {            @QueryHint(name = HibernateHints.HINT_CACHEABLE, value = "true"),            @QueryHint(name = HibernateHints.HINT_CACHE_REGION, value = BUCKETS_GLOBAL_REGION)    })    List<WeatherMapBucket> findByTimestampBucketLessThanAndIntervalMinutesOrderByTimestampBucketDesc(            Long timestampBucket, Integer intervalMinutes);}